    -- code-trend · Signal code trend [scope=security]
    ('analysis.signals.code-trend.trend_state', 'signals', 'code-trend', 'trend_state', 'Trend state', '', 'Signals-tier trend day state: 0 top | 1 bottom | 2 rise | 3 fall | 5 none. The regime context every rule cell conditions on — quote it first; the same trigger measures oppositely across states (the equity asymmetry axis).', '{"scope": "security", "rank": false, "page_title": "Signal code trend", "source": {"kind": "table", "table": "analysis.trend_days", "value": "trend", "date": "date", "code": "code", "sec_type": "sec_type"}, "sec_types": ["etf", "index", "stock"]}'::jsonb, 0),
