    ('analysis.signals.code-trend.chg_20d', 'signals', 'code-trend', 'chg_20d', '20d change', '%', '20-session close change — the monthly momentum gauge.', '{"scope": "security", "page_title": "Signal code trend", "source": {"kind": "compute", "fn": "pct_change", "args": {"days": 20}}}'::jsonb, 2),
